CGAL::Arrangement_2<CGAL::Exact_predicates_exact_constructions_kernel> arrangement;
for (const auto& segment : segments) {
    CGAL::Exact_predicates_exact_constructions_kernel::Segment_2 segment2(
        CGAL::Exact_predicates_exact_constructions_kernel::Point_2(segment.p1().x(), segment.p1().y()),
        CGAL::Exact_predicates_exact_constructions_kernel::Point_2(segment.p2().x(), segment.p2().y())
    );
    CGAL::insert(arrangement, segment2);
}
return arrangement;

